    s2 = doc.TextStyles.Add('simsun_test')
try:
    s2.FontFile = 'SimSun'
    print('FontFile=SimSun OK')
except Exception as e:
    print('FontFile=SimSun FAIL:', str(e)[:100])

# 测试 FontFile = 宋体 (no .ttf)
