python -c "
import win32com.client, pythoncom
acad = win32com.client.Dispatch('ZWCAD.Application')
doc = acad.ActiveDocument
if doc:
    ms = doc.ModelSpace
    lines=0; texts=0; dims=0
    bad_texts=[]
    bad_dims=[]
    for i in range(1, ms.Count+1):
        try:
            obj = ms.Item(i)
            nm = obj.ObjectName
            if nm == 'AcDbText':
                texts+=1
                if obj.StyleName != 'SHX_CN': bad_texts.append(obj.TextString)
            elif nm == 'AcDbLine': lines+=1
            elif 'Dimension' in nm or 'Dim' in nm:
                dims+=1
                if hasattr(obj,'TextStyle') and obj.TextStyle != 'SHX_CN': bad_dims.append(obj.TextStyle)
        except: pass

    print('Objects: {} lines, {} texts, {} dims'.format(lines, texts, dims))
    if bad_texts: print('BAD texts using wrong style: {}'.format(bad_texts[:3]))
    else: print('All texts OK (style=SHX_CN)')
    if bad_dims: print('BAD dims: {}'.format(bad_dims))
    else: print('All dims OK (textStyle=SHX_CN)')

    # Verify layers
    print('DIMTXSTY:', doc.GetVariable('DIMTXSTY'))
    print('TEXTSTYLE:', doc.GetVariable('TEXTSTYLE'))
" 2>&1

